/**
 * Excel's 60 built-in table styles (Light 1–21, Medium 1–28, Dark 1–11), read from Excel 16 through
 * COM (`Workbook.TableStyles(name).TableStyleElements`) and stored with their color REFERENCES
 * (theme slot + tint), so a workbook's own theme colors resolve them the way Excel does.
 * Generated — do not edit by hand.
 *
 * `EXACT_TINTS` carries the exact color Excel resolved for each base color and tint under the
 * Office, Office 2013–2022 and Office 2007–2010 schemes (a tint is an HLS lightness shift whose
 * rounding is not reproducible to the last digit); any other scheme falls back to the formula.
 */

export type ThemeSlot = 'lt1' | 'dk1' | 'lt2' | 'dk2' | 'a1' | 'a2' | 'a3' | 'a4' | 'a5' | 'a6'
export type BorderLine = 'thin' | 'medium' | 'thick' | 'double'

export interface ThemeColorRef {
  readonly s: ThemeSlot
  /// lighter (+) / darker (−), −1…1
  readonly t?: number
}

/// a color a user picked for a custom table style: the same in every theme
export interface RgbColorRef {
  readonly rgb: string
}

export type ColorRef = ThemeColorRef | RgbColorRef

export interface BorderDef {
  readonly l: BorderLine
  readonly c: ColorRef
}

export interface ElementDef {
  readonly fill?: ColorRef
  readonly font?: ColorRef
  readonly bold?: true
  readonly top?: BorderDef
  readonly bottom?: BorderDef
  readonly left?: BorderDef
  readonly right?: BorderDef
  readonly insideH?: BorderDef
  readonly insideV?: BorderDef
}

export interface TableStyleDef {
  readonly whole?: ElementDef
  readonly header?: ElementDef
  readonly total?: ElementDef
  readonly firstCol?: ElementDef
  readonly lastCol?: ElementDef
  readonly stripe1?: ElementDef
  readonly stripe2?: ElementDef
  readonly colStripe1?: ElementDef
  readonly colStripe2?: ElementDef
}

